% Thermal conductivity data
t = [0 1 2 3 4];
k = [0.10 0.25 0.35 0.40 0.42];

% Plot
figure; %[output:9e7c19fe]
plot(t, k, 'bo','MarkerSize', 7, 'MarkerFaceColor', 'b'); %[output:9e7c19fe]

% Labels and formatting
xlabel('t (s)', 'FontSize', 12); %[output:9e7c19fe]
ylabel('k (W/(m K))', 'FontSize', 12); %[output:9e7c19fe]
title('Coefficient of Thermal Conductivity k vs Time t', 'FontSize', 13); %[output:9e7c19fe]

grid on; %[output:9e7c19fe]
xlim([0 4]); %[output:9e7c19fe]
ylim([0 0.5]); %[output:9e7c19fe]

